// Auto-gerado de logo-ecosunpower-1024-transparente.png — logo oficial sem fundo (transparente), cores originais.
// [ECOSOF] A constante abaixo é o FALLBACK embutido (cliente nº 0 = EcoSunPower).
// obterLogoBase64() no fim do arquivo resolve a logo parametrizada via Storage.
import type { SupabaseClient } from '@supabase/supabase-js';
import { empresa } from '../../empresa-config.js';

export const LOGO_ECOSUNPOWER_BRANCO_BASE64 = "data:image/png;base64,";

// [ECOSOF] Logo da proposta/relatório parametrizada por empresa: quando
// empresa_config.logo_storage_path está setado, baixa do bucket privado
// 'branding' (1x por path — cache em memória pro PDF não baixar a cada
// geração); path vazio ou QUALQUER falha cai na logo EcoSun embutida acima.
// Com o seed EcoSun (logo_storage_path = null) a saída é byte-idêntica ao
// comportamento antigo. A logo "branca" usada no dashboard segue embutida
// de propósito (YAGNI — só os pontos de geração de PDF chamam esta função).
const logoCachePorPath = new Map<string, string>();

// Whitelist de MIME pra logo embutida em data URI nos PDFs/HTML.
// SVG fica FORA por princípio (pode carregar script); sem content-type
// assume PNG (comportamento antigo — Storage nem sempre devolve type).
const LOGO_MIMES_PERMITIDOS = new Set(['image/png', 'image/jpeg', 'image/webp']);

export async function obterLogoBase64(client: SupabaseClient): Promise<string> {
  const path = empresa().logoStoragePath;
  if (!path) return LOGO_ECOSUNPOWER_BRANCO_BASE64;
  const cached = logoCachePorPath.get(path);
  if (cached) return cached;
  try {
    const { data, error } = await client.storage.from('branding').download(path);
    if (error || !data) throw new Error(error?.message ?? 'download vazio');
    const buf = Buffer.from(await data.arrayBuffer());
    if (buf.length === 0) throw new Error('arquivo vazio');
    if (data.type && !LOGO_MIMES_PERMITIDOS.has(data.type)) {
      console.warn(`[logo] branding/${path} recusada — MIME nao permitido (${data.type}); aceitos: png/jpeg/webp. Usando logo embutida.`);
      return LOGO_ECOSUNPOWER_BRANCO_BASE64;
    }
    const mime = data.type || 'image/png';
    const dataUri = `data:${mime};base64,${buf.toString('base64')}`;
    logoCachePorPath.set(path, dataUri);
    return dataUri;
  } catch (err) {
    console.warn(`[logo] download de branding/${path} falhou — usando logo embutida:`, (err as Error).message);
    return LOGO_ECOSUNPOWER_BRANCO_BASE64;
  }
}

// Logo para FUNDO ESCURO (letra prateada/branca, transparente, SEM caixa). Fonte: Marketing/logos/Logo nova/ecosun png.png
export const LOGO_ECOSUNPOWER_DARK_BASE64 = "data:image/png;base64,";
